mapper.select:
SELECT r.id, r.name, r.trigger_code, r.status, r.scope_json, r.condition_json, r.actions_json, r.debounce_hours, r.daily_limit, r.template_code, r.trigger_count, r.last_trigger_time, r.last_result, r.remark, r.create_by, r.create_time, r.update_time, u.nickname AS create_by_name, (SELECT COUNT(*) FROM ecom_auto_log l WHERE l.rule_id = r.id AND l.result IN ('FAILED', 'PARTIAL') AND l.create_time >= #{failedSince}) AS failed_count FROM ecom_auto_rule r LEFT JOIN sys_user u ON u.id = r.create_by
AND (r.name LIKE CONCAT('%', #{keyword}, '%') OR r.remark LIKE CONCAT('%', #{keyword}, '%')) AND r.trigger_code = #{trigger} AND r.status = #{status}
ORDER BY r.status DESC, r.id DESC
